(7357413, 1152033, 62249, '<td valign="top">Nice juxtaposition and good use of lighting/shadow.</td>', 'Nice juxtaposition and good use of lighting/shadow.', '2015-06-05 01:40:09.000000', NULL, 1),
(7357415, 1152015, 50641, '<td valign="top">Not with thai basil!</td>', 'Not with thai basil!', '2015-06-05 01:41:48.000000', NULL, 1),
